import React, { useState, useEffect } from "react";
import { Link } from "react-router-dom";
import {
  HouseDoorFill,
  ListCheck,
  Calendar3,
  BarChart,
  People,
  Gear,
  QuestionCircle,
  BoxArrowRight,
  List,
  Clipboard,
  PersonLinesFill,
  Kanban,
  Check2Square,
  Person,
  Question,
  QuestionCircleFill,
  Line,
  HddRack,
  Back
} from "react-bootstrap-icons";
import {
  Archive, CheckSquare, ClipboardList, Cpu, Database,
  Factory, GitBranch, LayoutDashboard, ListTodo, MapPin,
  ShieldCheck, WashingMachine, Workflow
} from "lucide-react";
import "bootstrap/dist/css/bootstrap.min.css";
import "../css/SideBar.css"
import { usePermissionStore } from "../auth/Permission";
import { FaBookOpen, FaPlusCircle } from "react-icons/fa";
import { FaCogs } from "react-icons/fa"
import { FaProjectDiagram } from "react-icons/fa";
import { RiDashboard2Fill } from "react-icons/ri";
import { OverlayTrigger, Tooltip } from "react-bootstrap";

const Sidebar = ({ moduleName }) => {
  // const [moduleName, setModuleName] = useState(moduleName);
  const [isCollapsed, setIsCollapsed] = useState(false);
  // const hasPermission = usePermissionStore((state) => state.hasPermission);
  const permissions = usePermissionStore((state) => state.permissions);
  // simple permission checker
  const hasPermission = (permissionName) => permissions.includes(permissionName);

  // Auto-collapse if screen < 1000px
  useEffect(() => {
    const handleResize = () => {
      if (window.innerWidth < 1500) {
        setIsCollapsed(true);
      } else {
        setIsCollapsed(false);
      }
    };
    window.addEventListener("resize", handleResize);
    handleResize(); // run on load
    return () => window.removeEventListener("resize", handleResize);
  }, []);
  return (
    <div
      className="d-flex flex-column text-white"
      style={{
        width: isCollapsed ? "50px" : "260px",
        height: "100vh",
        position: "sticky",
        top: 0,
        backgroundColor: "#0f6b5b"
      }}
    >
      {/* Toggle Button */}
      <button
        className="btn btn-sm btn-outline-light m-2 p-0"
        onClick={() => setIsCollapsed(!isCollapsed)}
      >
        <List size={28} />
      </button>

      {/* Logo */}
      {!isCollapsed && (
        <a
          href="/WebApplication/dashboard"
          className="d-flex align-items-center mb-3 text-white text-decoration-none px-3"
        >
          <span className="fs-5 fw-bold">
            <Database size={20} className="me-2" />
            {moduleName}
          </span>
        </a>
      )}

      <hr className="border-light mx-2" />

      <ul className="nav nav-pills flex-column mb-auto">

        {[
          { key: "plantMaster", label: "Plant Master", icon: <Factory size={20} /> },
          { key: "locationMaster", label: "Location Master", icon: <MapPin size={20} /> },
          { key: "rackMaster", label: "Rack Master", icon: <Archive size={20} /> },
          { key: "roleMaster", label: "Role Master", icon: <Cpu size={20} /> },
          { key: "processMaster", label: "Process Master", icon: <Workflow size={20} /> },
          { key: "devicesMaster", label: "Devices Master", icon: <GitBranch size={20} /> },
          { key: "storeMaterialCategoryMaster", label: "Store Material Category Master", icon: <GitBranch size={20} /> },
          { key: "storeMaterialMaster", label: "Store Material Master", icon: <GitBranch size={20} /> },
          { key: "productionArticleCategoryMaster", label: "Production Article Category Master", icon: <Workflow size={20} /> },
          { key: "productionArticleMaster", label: "Production Article Master", icon: <Workflow size={20} /> }
        ].map(item =>
          hasPermission(item.key) && (
            <li className="nav-item" key={item.key}>
              {isCollapsed ? (
                <OverlayTrigger
                  placement="right"
                  container={document.body}
                  overlay={
                    <Tooltip id={`tooltip-${item.key}`}>
                      {item.label}
                    </Tooltip>
                  }
                >
                  <div style={{ display: "inline-block", width: "100%" }}>
                    <Link
                      to={item.key}
                      className="nav-link text-white d-flex justify-content-center align-items-center sidebar-link"
                    >
                      {item.icon}
                    </Link>
                  </div>
                </OverlayTrigger>
              ) : (
                <Link
                  to={item.key}
                  className="nav-link text-white d-flex align-items-center px-3 sidebar-link"
                >
                  <span className="me-2">{item.icon}</span>
                  {item.label}
                </Link>
              )}
            </li>
          )
        )}

      </ul>

      <hr className="border-light mx-2" />

      {/* Logout */}
      <ul className="nav nav-pills flex-column">

        <li className="nav-item">

          <OverlayTrigger
            placement="right"
            // container={document.body}
            overlay={
              <Tooltip id={`tooltip-back`}>
                Back To Dashboard
              </Tooltip>
            }
          >
            <Link
              to="/WebApplication/moduleDashboard"
              className="nav-link text-white d-flex align-items-center px-3 sidebar-link"
            >
              <Back size={20} className="me-2" />
              {!isCollapsed && "Go To Dashboard"}
            </Link>
          </OverlayTrigger>
        </li>

        <li className="nav-item">
          <Link
            to="logout"
            className="nav-link text-white d-flex align-items-center px-3 sidebar-link"
          >
            <BoxArrowRight size={20} className="me-2" />
            {!isCollapsed && "Logout"}
          </Link>
        </li>
      </ul>
    </div>
  );
};

export default Sidebar;
